package com.example.expensetracker.controller;

import com.example.expensetracker.dto.FinancialIntelligenceDto;
import com.example.expensetracker.dto.WealthSimulationRequest;
import com.example.expensetracker.dto.WealthSimulationResponse;
import com.example.expensetracker.security.UserSecurity;
import com.example.expensetracker.service.FinancialIntelligenceService;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.ResponseEntity;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class FinancialIntelligenceControllerTest {

    @Mock
    private FinancialIntelligenceService intelligenceService;

    @Mock
    private UserSecurity userSecurity;

    @InjectMocks
    private FinancialIntelligenceController controller;

    @Test
    @DisplayName("GET /api/intelligence/user/{userId} validates user access and returns snapshot")
    void getIntelligenceSnapshot_returns200() {
        FinancialIntelligenceDto expected = new FinancialIntelligenceDto(
                88, "A", Map.of("savingsRetention", 90),
                new BigDecimal("100000.00"), new BigDecimal("45000.00"), new BigDecimal("55000.00"),
                55.0, new BigDecimal("1500.00"), new BigDecimal("45000.00"), new BigDecimal("2500.00"),
                15, 3, new BigDecimal("100000.00"), new BigDecimal("2000.00"), 5000.0,
                List.of(), List.of("Great pace")
        );
        when(intelligenceService.getIntelligenceSnapshot(1L)).thenReturn(expected);

        ResponseEntity<FinancialIntelligenceDto> response = controller.getIntelligenceSnapshot(1L);

        verify(userSecurity).validateUserAccess(1L);
        assertEquals(200, response.getStatusCode().value());
        assertEquals(expected, response.getBody());
    }

    @Test
    @DisplayName("POST /api/intelligence/user/{userId}/simulate validates user access and returns simulation")
    void simulateWealthTrajectory_returns200() {
        WealthSimulationRequest req = new WealthSimulationRequest(
                new BigDecimal("5000.00"), BigDecimal.ZERO, BigDecimal.ZERO, 12);
        WealthSimulationResponse expected = new WealthSimulationResponse(
                12, new BigDecimal("30000.00"), new BigDecimal("35000.00"),
                new BigDecimal("360000.00"), new BigDecimal("420000.00"), new BigDecimal("60000.00"),
                43.8, 5, 1, "Summary"
        );
        when(intelligenceService.simulateWealthTrajectory(1L, req)).thenReturn(expected);

        ResponseEntity<WealthSimulationResponse> response = controller.simulateWealthTrajectory(1L, req);

        verify(userSecurity).validateUserAccess(1L);
        assertEquals(200, response.getStatusCode().value());
        assertEquals(expected, response.getBody());
    }
}

