package com.example.expensetracker.service.impl;

import com.example.expensetracker.dto.FinancialIntelligenceDto;
import com.example.expensetracker.dto.WealthSimulationRequest;
import com.example.expensetracker.dto.WealthSimulationResponse;
import com.example.expensetracker.model.*;
import com.example.expensetracker.repository.*;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class FinancialIntelligenceServiceImplTest {

    @Mock private UserRepository userRepository;
    @Mock private ExpenseRepository expenseRepository;
    @Mock private IncomeRepository incomeRepository;
    @Mock private BudgetRepository budgetRepository;
    @Mock private RecurringExpenseRepository recurringExpenseRepository;
    @Mock private SavingsGoalRepository savingsGoalRepository;
    @Mock private LoanAdjustmentRepository loanAdjustmentRepository;

    @InjectMocks
    private FinancialIntelligenceServiceImpl intelligenceService;

    private User testUser;

    @BeforeEach
    void setUp() {
        testUser = new User();
        testUser.setId(1L);
        testUser.setName("Test User");
        testUser.setEmail("test@example.com");
        testUser.setCurrency("INR");
    }

    @Test
    @DisplayName("getIntelligenceSnapshot computes composite health score and 6-month forecast")
    void getIntelligenceSnapshot_computesMetricsAndForecast() {
        LocalDate today = LocalDate.now();
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));
        when(incomeRepository.findByUser(testUser)).thenReturn(List.of(
                Income.builder().id(10L).user(testUser).source("Primary Salary").amount(new BigDecimal("100000.00")).incomeDate(today.withDayOfMonth(1)).isRecurring(true).frequency("MONTHLY").build()
        ));
        when(expenseRepository.findByUser(testUser)).thenReturn(List.of(
                Expense.builder().id(20L).user(testUser).description("Groceries").amount(new BigDecimal("25000.00")).expenseDate(today.withDayOfMonth(1)).isRecurring(false).build()
        ));
        when(budgetRepository.findByUser(testUser)).thenReturn(List.of(
                Budget.builder().id(30L).user(testUser).limitAmount(new BigDecimal("60000.00")).build()
        ));
        when(recurringExpenseRepository.findByUser(testUser)).thenReturn(List.of());
        when(savingsGoalRepository.findByUser(testUser)).thenReturn(List.of(
                SavingsGoal.builder().id(50L).user(testUser).name("Emergency Reserve").targetAmount(new BigDecimal("300000.00")).currentAmount(new BigDecimal("150000.00")).build()
        ));
        when(loanAdjustmentRepository.findByUserOrderByAdjustmentDateDescIdDesc(testUser)).thenReturn(List.of());

        FinancialIntelligenceDto dto = intelligenceService.getIntelligenceSnapshot(1L);
        assertNotNull(dto);
        assertTrue(dto.healthScore() >= 75);
        assertEquals(6, dto.sixMonthForecast().size());
    }
}
